        RateLog copy = new RateLog();
        copy.sheetId = sheetId;
        copy.grade = grade;
        copy.fromDate = fromDate;
        copy.toDate = toDate;
        copy.pct = pct;
        copy.setOn = setOn;
        copy.forwardAfter = forwardAfter;
        return copy;
    }

